import{_ as a}from"./chunks/architecture.BrenojrM.js";import{_ as d,o as l,c as i,a2 as n}from"./chunks/framework.ifFCyy4k.js";const b=JSON.parse('{"title":"組裝總覽與里程碑","description":"","frontmatter":{},"headers":[],"relativePath":"build/overview.md","filePath":"build/overview.md","lastUpdated":1793016282000}'),s={name:"build/overview.md"};function e(r,t,p,o,h,c){return l(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="組裝總覽與里程碑" tabindex="-1">組裝總覽與里程碑 <a class="header-anchor" href="#組裝總覽與里程碑" aria-label="Permalink to &quot;組裝總覽與里程碑&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 記憶體與磁碟占用為研究 2 的推論值, 實機驗證前請視為推估值; 里程碑 3 圖中 Keycloak, OPA, ToolHive, gVisor, ModelAudit 的設定未實機驗證</li></ul></div><p><strong>結論</strong>: 第二部的十個模組依相依關係由下往上組裝, 中途有三個里程碑, 每個里程碑都是可以獨立使用的系統. 單人組到里程碑 1; 2 至 10 人且需要檢索, 組到里程碑 2; 多人, 多模型且有人每週維運 (並符合 M5.1 節條件), 才組到里程碑 3.</p><table tabindex="0"><thead><tr><th>里程碑</th><th>完成的模組</th><th>適用</th><th>建議硬體等級</th><th>額外占用 (推論)</th></tr></thead><tbody><tr><td>1. 能對話 (最小安全組合)</td><td>M0 至 M2</td><td>單人, 單機</td><td>A 至 F</td><td>介面約 0.5 至 1.5GB 記憶體; 磁碟約 2 至 5GB (不含模型)</td></tr><tr><td>2. 能查文件, 能多人用 (標準組合)</td><td>再加 M3 至 M6</td><td>家庭或小團隊 2 至 10 人</td><td>B, D, E; C 級須為中高記憶體款</td><td>嵌入模型約 0.6 至 1.2GB; 向量庫約 1 至 2GB; 磁碟約 10 至 30GB</td></tr><tr><td>3. 能動手做事 (進階組合)</td><td>再加 M7 至 M9</td><td>多人, 多模型, 含閘道, 代理與沙箱</td><td>F</td><td>閘道加 PostgreSQL 約 1 至 2GB; 磁碟約 50 至 100GB</td></tr></tbody></table><p>資料來源: 研究 2 (2026-10-26), 占用值由各元件公開資料加總推算, 信心: 中.</p><h2 id="組裝順序與相依關係" tabindex="-1">組裝順序與相依關係 <a class="header-anchor" href="#組裝順序與相依關係" aria-label="Permalink to &quot;組裝順序與相依關係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>需要先完成</th><th>為什麼排在這裡</th></tr></thead><tbody><tr><td>M0 基礎環境</td><td>無</td><td>網段, 主機與備份要先就位, 之後每個模組都放在這個環境裡</td></tr><tr><td>M1 推論伺服器</td><td>M0</td><td>沒有模型就沒有服務, 先確認硬體跑得動</td></tr><tr><td>M2 使用者介面與反向代理</td><td>M1</td><td>介面要連到推論伺服器才能驗收</td></tr><tr><td>M3 模型入庫與存放</td><td>M0</td><td>模型變多之前, 先把來源與檢查流程固定下來</td></tr><tr><td>M4 檢索 (RAG)</td><td>M1, M2</td><td>嵌入模型跑在推論伺服器, 使用者在介面中提問</td></tr><tr><td>M5 模型閘道與身分驗證</td><td>M1, M2</td><td>多人共用時, 介面改經閘道連模型, 帳號改由身分驗證伺服器管理</td></tr><tr><td>M6 可觀測, 稽核與評估</td><td>M5</td><td>閘道是蒐集呼叫紀錄的集中點; 測試集從里程碑 1 就可以開始建</td></tr><tr><td>M7 工具與沙箱</td><td>M5, M6</td><td>工具會改變系統狀態, 先有紀錄才開放</td></tr><tr><td>M8 代理與治理</td><td>M7</td><td>代理只能透過工具閘道動手, 所以工具要先就位</td></tr><tr><td>M9 流程自動化</td><td>M5, M7</td><td>n8n 只經模型閘道與工具閘道對外, 不直接保存金鑰</td></tr></tbody></table><h2 id="里程碑-1-能對話-最小安全組合" tabindex="-1">里程碑 1: 能對話 (最小安全組合) <a class="header-anchor" href="#里程碑-1-能對話-最小安全組合" aria-label="Permalink to &quot;里程碑 1: 能對話 (最小安全組合)&quot;">​</a></h2><p><strong>元件</strong>: 推論伺服器 (llama.cpp 或 Ollama, 見 M1), 加上一個介面 (見 M2). 等級 A 與 C 建議用 AnythingLLM 桌面版, 其他等級用 Open WebUI 單一容器. 不加閘道, 代理框架與 MCP.</p><p><strong>啟動順序</strong>: 推論引擎 → 介面.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[瀏覽器 / 桌面 App]</span></span>
<span class="line"><span>      | http://127.0.0.1:3000</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Open WebUI 或 AnythingLLM] ----&gt; [Ollama / llama-server]</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   (本機資料卷: 對話, 設定) --&gt; 每週備份</span></span>
<span class="line"><span>   對外: 無開放連接埠</span></span></code></pre></div><p><strong>里程碑 1 檢核表</strong></p><ul><li>[ ] 所有服務只綁 127.0.0.1</li><li>[ ] 映像或安裝版本已記錄並鎖定</li><li>[ ] 介面已設管理者密碼, 並關閉公開註冊</li><li>[ ] 每週備份資料卷</li><li>[ ] 每週檢查一次安全公告, 每月評估一次是否升級 (見 O2, O3)</li><li>[ ] 不在介面中存放雲端 API 金鑰, 或只放低額度金鑰</li></ul><p>用 Docker 執行介面時的連接埠與位址設定, 見 M2.</p><h2 id="里程碑-2-能查文件-能多人用-標準組合" tabindex="-1">里程碑 2: 能查文件, 能多人用 (標準組合) <a class="header-anchor" href="#里程碑-2-能查文件-能多人用-標準組合" aria-label="Permalink to &quot;里程碑 2: 能查文件, 能多人用 (標準組合)&quot;">​</a></h2><p><strong>元件</strong>:</p><ul><li>推論引擎, 搭配 llama-swap (需要多模型輪替時)</li><li>介面: Open WebUI 或 LibreChat</li><li>嵌入模型: Qwen3-Embedding-0.6B 或 bge-m3</li><li>向量庫: 介面內建的, 或 Qdrant</li><li>文件解析: Docling</li><li>評估: promptfoo 測試集 (M6)</li><li>網路: 只限內網 (辦公室或機房的區域網路)</li></ul><p><strong>啟動順序</strong>: 推論引擎 / llama-swap → 向量庫 → 介面 → (排程) 文件解析與匯入 → promptfoo 驗證.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[家人 / 同事裝置] --內網 HTTPS--&gt; [主機 192.168.x.y]</span></span>
<span class="line"><span>                                              |</span></span>
<span class="line"><span>                     +------------------------+-----------------+</span></span>
<span class="line"><span>                     v                        v                 v</span></span>
<span class="line"><span>               [Open WebUI / LibreChat]  [Qdrant :6333]    [Docling 批次]</span></span>
<span class="line"><span>                     |  (內部 Docker 網路, 不對外)</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>               [llama-swap :8080] --&gt; [llama-server: 對話模型 / 嵌入模型]</span></span>
<span class="line"><span>   公網: 無連接埠轉發</span></span></code></pre></div><p><strong>里程碑 2 檢核表 (在里程碑 1 之上, 另加)</strong>:</p><ul><li>[ ] 以主機防火牆限定可連入的內網網段</li><li>[ ] 每位使用者使用個別帳號</li><li>[ ] RAG 文件來源只限可信資料夾 (對應 OWASP LLM08 與 ASI06, 見 K6.4 節)</li><li>[ ] 升級前先跑 promptfoo 測試集</li><li>[ ] <code>.env</code> 權限設為 600</li></ul><h2 id="里程碑-3-能動手做事-進階組合-◇" tabindex="-1">里程碑 3: 能動手做事 (進階組合) ◇ <a class="header-anchor" href="#里程碑-3-能動手做事-進階組合-◇" aria-label="Permalink to &quot;里程碑 3: 能動手做事 (進階組合) ◇&quot;">​</a></h2><p><strong>使用條件</strong>: 有人能每週維運, 且符合 M5.1 節列出的閘道條件. 若不符, 請停在里程碑 2.</p><p><strong>元件</strong>: 標準組合全部, 加上:</p><ul><li>推論伺服器: vLLM (多人同時使用時, 吞吐量明顯高於 llama.cpp 與 Ollama)</li><li>閘道: LiteLLM 或 Bifrost 擇一, 以映像摘要值 (digest) 鎖定版本</li><li>反向代理: Nginx 或 Caddy, 只接受內網連線</li><li>身分驗證 (可選): Keycloak, 以 OIDC 提供單一登入</li><li>代理: LangGraph 程式庫, 嵌入自己撰寫的服務; 搭配 OPA 政策引擎</li><li>隔離模型: 自建程式加本地模型, 專門讀取不可信內容, 不給任何工具</li><li>工具閘道: MCP gateway (ToolHive 等), 加上少量已審核, 已容器化的 MCP 伺服器</li><li>程式碼沙箱: Docker 加 gVisor</li><li>模型入庫檢查 (ModelAudit 等) 與 NFS 唯讀的模型存放區</li><li>可選: n8n (規則固定的流程自動化), Langfuse (另備至少 12GB 記憶體給 ClickHouse 與 Redis 等), OTel Collector, Prometheus 與 Grafana, Prompt Guard 2 22M</li></ul><p><strong>啟動順序</strong>: PostgreSQL / Redis → 推論伺服器 / llama-swap → 閘道 → 向量庫 → OPA → MCP gateway 與 MCP 伺服器 (容器) → 代理服務 → n8n → Keycloak → 介面 → 反向代理 → 可觀測性.</p><p><img src="`+a+'" alt="里程碑 3 的完整部署架構"></p><p>這張圖就是<a href="/lanai-handbook/start/map">架構地圖</a>上的終點. 珊瑚色元件接觸不可信內容, 紫色是可信控制區, 米色是基礎設施; 粗框是實體主機, 細框是 VM, 點線框是設備. 方塊上方是要安裝的軟體, 下方是角色.</p><p><strong>部署分區</strong>: 以 Proxmox VE 的 VM 劃分信任區, 接觸不可信內容的元件一律放 VM, 不放 LXC 容器 (LXC 與主機共用核心, 隔離較弱; 推論, 信心: 中).</p><table tabindex="0"><thead><tr><th>VM 區</th><th>放什麼</th><th>網路限制</th></tr></thead><tbody><tr><td>入口區</td><td>反向代理, 介面, Keycloak, Docling, Qdrant</td><td>只接受內網使用者連線</td></tr><tr><td>控制區</td><td>LangGraph, OPA</td><td>只能連閘道區與隔離區</td></tr><tr><td>隔離區</td><td>隔離模型</td><td>只能連 LiteLLM, 不持有任何工具憑證</td></tr><tr><td>閘道區</td><td>LiteLLM, MCP gateway</td><td>唯一保存 API 金鑰, 唯一能對外連線的區</td></tr><tr><td>工具區</td><td>MCP 伺服器, 程式碼沙箱</td><td>沙箱無網路; MCP 伺服器只能連指定系統</td></tr><tr><td>推論區</td><td>vLLM (GPU 直通)</td><td>只接受閘道區連線</td></tr><tr><td>稽核區</td><td>Langfuse, OTel Collector, Prometheus</td><td>只接收紀錄, 轉送既有 SIEM</td></tr><tr><td>自動化區</td><td>n8n</td><td>只能連閘道區 (LiteLLM, MCP gateway)</td></tr></tbody></table><p>資料來源: 分區方式整理自 2026-10 的藍隊代理架構模擬與研究 2, 屬推論, 信心: 中. 實際部署前請以自己的網段與防火牆規則驗證.</p><p><strong>里程碑 3 檢核表 (在里程碑 2 之上, 另加)</strong>:</p><ul><li>[ ] 閘道與 MCP 映像以摘要值鎖定, 並訂閱 GitHub Security Advisories</li><li>[ ] 閘道管理端點只限管理者 IP</li><li>[ ] 每位使用者或每個應用各一把虛擬金鑰, 並設用量上限</li><li>[ ] 代理的寫入與刪除動作需要人工確認</li><li>[ ] 沙箱無網路, 並有資源上限</li><li>[ ] MCP 工具描述變更時重新審核</li><li>[ ] 金鑰輪替流程已準備, 並演練過一次</li><li>[ ] 推論伺服器只接受閘道連線</li><li>[ ] 模型檔入庫前掃描並記錄雜湊值, 推論伺服器以唯讀方式掛載</li><li>[ ] n8n 不保存外部系統金鑰, 工具一律經 MCP gateway 呼叫</li></ul><h2 id="硬體等級對應" tabindex="-1">硬體等級對應 <a class="header-anchor" href="#硬體等級對應" aria-label="Permalink to &quot;硬體等級對應&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等級</th><th>建議架構</th><th>備註</th></tr></thead><tbody><tr><td>A 無獨顯筆電</td><td>最小組合 (AnythingLLM 桌面版)</td><td>RAG 只用小型嵌入模型; 不跑代理</td></tr><tr><td>B 8 至 12GB 顯示卡</td><td>最小組合, 或精簡標準組合</td><td>嵌入模型放 CPU, 保留顯示記憶體</td></tr><tr><td>C Apple Silicon</td><td>16GB 用最小組合; 32GB 以上可用標準組合</td><td>依統一記憶體決定</td></tr><tr><td>D 16GB 顯示卡</td><td>標準組合</td><td>llama-swap 輪替對話與嵌入模型</td></tr><tr><td>E</td><td>標準組合; 小團隊可加 LangGraph</td><td>使用 Langfuse 須確認系統記憶體 32GB 以上</td></tr><tr><td>F</td><td>進階組合</td><td>有人能每週維運時才採用</td></tr></tbody></table><p>資料來源: 研究 2 第 12.4 節, 屬推論, 信心: 中.</p>',36)])])}const u=d(s,[["render",e]]);export{b as __pageData,u as default};
